15	// either a local or remote URL. Plan Map data supplies these paths, but this
16	// guard means a malformed entry cannot escape the intended document root.
17	const repositoryPath = (value) => {
18	  const parts = String(value ?? '').replace(/\\/g, '/').split('/');
19	  if (!parts.length || parts.some((part) => !part || part === '.' || part === '..')) {
20	    throw new Error(`Invalid repository document path: ${value}`);
21	  }
22	  return parts.map(encodeURIComponent).join('/');
23	};
24	
25	// A browser cannot discover the developer's checkout from a static host. Keep
26	// the local bridge as an explicit opt-in so static pages consistently link to
27	// the reviewed canonical repository rather than emitting a broken /@fs URL.
28	export const createDocLinkResolver = ({
29	  appBase = '/Aralia',
30	  repoRoot = '',
31	  repository = CANONICAL_REPOSITORY,
32	  ref = CANONICAL_REF,
33	  useFsBridge = false,
34	} = {}) => {
