39	  const mode = useFsBridge && normalizedRoot ? 'vite-fs' : 'github';
40	
41	  // Use the same resolved path for every destination. Direct links should show
42	  // the source file in GitHub; drawer fetches need raw Markdown that the local
43	  // renderer can turn into readable HTML.
