                             "status":  "done",
                             "link":  "docs/superpowers/specs/2026-07-06-staged-offthread-3d-world-entry-design.md",
                             "open":  1
                         },
                         {
                             "title":  "Walking stutter fixed Ã¢â‚¬â€ off-thread ground chunk meshing",
                             "status":  "done",
                             "link":  "docs/superpowers/specs/2026-07-07-offthread-ground-chunk-meshing-design.md",
                             "open":  1
                         }
                     ],
        "history":  {
                        "built":  "2026-07-07"
                    },
        "tier":  "strategic",
        "updated":  "2026-08-08"
    },
    {
        "id":  "building-generator",
        "title":  "Building blueprint pipeline",
        "sub":  "blueprint-first: design the 2D blueprint, build 3D from ONE shared data shape (rooms/doors/walls/stairs in feet)",
        "campaign":  "world",
        "subcampaign":  "Interiors \u0026 Buildings",
        "status":  "done",
        "deps":  [
                     {
                         "id":  "wf-interiors",
                         "kind":  "chosen",
                         "why":  "Grows the L4 interior generator into the shared building-maker rather than forking a second one: it already emits pure InteriorPlan data (rooms/doorways/furnishings/stairs, feet-canon 5 ft) and feeds the 3D build Ã¢â‚¬â€ the pipeline extends that data shape. Reverse experiment 2026-07-05 (PreviewBlueprint) proved one shared renderer serves the 2D blueprint AND the 3D build both ways"
                     },
                     {
                         "id":  "world-props",
                         "kind":  "hard",
                         "feature":  "prop-schema-placement-engine",
                         "why":  "Interior furniture IS props: beds, tables, hearths, counters, barrels place through the prop schema + placement engine (with referee data) Ã¢â‚¬â€ same system dungeon dressing uses, no prop system no furnishing"
                     },
                     {
                         "id":  "fip-slice1",
                         "kind":  "chosen",
                         "why":  "Walls carry real thickness on the grid line so combat reads cover: the blueprint\u0027s wall model feeds the fight-in-place 5 ft tile referee Ã¢â‚¬â€ a building interior IS a combat surface"
                     }
                 ],
        "link":  "docs/superpowers/specs/2026-07-05-building-blueprint-pipeline-design.md",
        "features":  [
                         {
                             "title":  "Blueprint data contract (rooms/doors/windows/furniture/stairs/walls, feet)",
                             "status":  "done"
                         },
                         {
                             "title":  "Believable layout (room purposes, dominant main room, real corridors, sensible entrance)",
                             "status":  "done"
                         },
                         {
                             "title":  "Module-map 2D blueprint drawer (pure view; scale bar + room numbers)",
                             "status":  "done"
                         },
                         {
                             "title":  "Walls as real-thickness grid edges (cover for the referee)",
                             "status":  "done"
                         },
                         {
                             "title":  "Basements + multi-storey",
                             "status":  "done"
                         },
                         {
                             "title":  "Irregular footprints (L-shapes, wings, tower) raised in 3D",
                             "status":  "done"
                         }
                     ],
        "tier":  "strategic"
    }
]

